PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS farmers(farmer_id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT UNIQUE NOT NULL,address TEXT,password TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers(customer_id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT UNIQUE NOT NULL,address TEXT,password TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(product_id INTEGER PRIMARY KEY AUTOINCREMENT,farmer_id INTEGER NOT NULL REFERENCES farmers(farmer_id) ON DELETE CASCADE,product_name TEXT NOT NULL,category TEXT,price REAL NOT NULL CHECK(price>0),quantity INTEGER NOT NULL CHECK(quantity>=0),image TEXT,unit TEXT NOT NULL DEFAULT 'kg',description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(order_id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,total_amount REAL NOT NULL,status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Confirmed','Delivered','Cancelled')),address TEXT);
CREATE TABLE IF NOT EXISTS order_items(order_item_id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,quantity INTEGER NOT NULL CHECK(quantity>0),price REAL NOT NULL);
CREATE TABLE IF NOT EXISTS admin(admin_id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL);
